package com.example.rokidkeyboardbridge;
import android.graphics.*;import android.view.View;import java.io.InputStream;
/** Six reviewed keyframes, one fixed person scale. Bounded decode and finite playback. */
final class PostureBridgeRenderer {
 static final String ASSET="loki_posture_bridge_v686.png";static final long DURATION=1850;
 private float[] geometry;private long retryAfter;private final View host;private Bitmap[] frames;private boolean loading,reverse;private long started=-1;private int generation;private final Paint paint=new Paint(3);private final RectF dst=new RectF();
 PostureBridgeRenderer(View host){this.host=host;}
 static int frame(long elapsed,boolean seated){float p=Math.max(0,Math.min(1,elapsed/(float)DURATION));p=p*p*(3-2*p);int index=Math.min(5,(int)(p*6));return seated?5-index:index;}
 boolean active(long now){return started>=0&&now>=started&&now-started<DURATION;}
 void cancel(){started=-1;}
 void start(boolean seated,long now){reverse=seated;started=now;request();}
 void request(){if(frames!=null||loading||android.os.SystemClock.uptimeMillis()<retryAfter)return;loading=true;final int token=generation;new Thread(()->{Bitmap atlas=null;Bitmap[] result=null;try(InputStream in=host.getContext().getAssets().open(ASSET)){atlas=BitmapFactory.decodeStream(in);if(atlas==null)throw new IllegalStateException("bridge missing");result=new Bitmap[6];for(int i=0;i<6;i++){int split=atlas.getHeight()*460/1024,x=i%3*atlas.getWidth()/3,y=i<3?0:split,ch=i<3?split:atlas.getHeight()-split;Bitmap cell=Bitmap.createBitmap(atlas,x,y,atlas.getWidth()/3,ch);result[i]=cell.copy(Bitmap.Config.ARGB_8888,true);cell.recycle();}}catch(Exception|OutOfMemoryError e){if(result!=null)for(Bitmap b:result)if(b!=null)b.recycle();result=null;}finally{if(atlas!=null)atlas.recycle();}float[] measured=null;try{if(result!=null){measured=new float[6*4+1];float[] centers={.510f,.510f,.512f,.547f,.504f,.490f};float left=0,right=0,span=1;for(int i=0;i<6;i++){Bitmap b=result[i];int[] px=new int[b.getWidth()*b.getHeight()];b.getPixels(px,0,b.getWidth(),0,0,b.getWidth(),b.getHeight());int lo=b.getWidth(),hi=0,top=b.getHeight(),bottom=0;for(int y=0;y<b.getHeight();y++)for(int x=0;x<b.getWidth();x++){int value=px[y*b.getWidth()+x];if(Math.max((value>>16)&255,Math.max((value>>8)&255,value&255))<=12)px[y*b.getWidth()+x]=Color.BLACK;else if((value&255)>32){lo=Math.min(lo,x);hi=Math.max(hi,x);top=Math.min(top,y);bottom=Math.max(bottom,y);}}b.setPixels(px,0,b.getWidth(),0,0,b.getWidth(),b.getHeight());float head=centers[i]*b.getWidth();measured[i*4]=head;measured[i*4+1]=bottom;measured[i*4+2]=lo-head;measured[i*4+3]=hi-head;left=Math.min(left,lo-head);right=Math.max(right,hi-head);span=Math.max(span,bottom-top);}for(int i=0;i<6;i++){measured[i*4+2]=left;measured[i*4+3]=right;}measured[24]=span;}}catch(RuntimeException|OutOfMemoryError e){if(result!=null)for(Bitmap b:result)if(b!=null&&!b.isRecycled())b.recycle();result=null;measured=null;}
final float[] anchors=measured;final Bitmap[] decoded=result;host.post(()->{if(token!=generation){if(decoded!=null)for(Bitmap b:decoded)b.recycle();return;}loading=false;frames=decoded;geometry=anchors;retryAfter=decoded==null?android.os.SystemClock.uptimeMillis()+60000:0;host.invalidate();});},"LokiPostureBridge").start();}
 private void single(Canvas c,int width,int height,int index,int alpha){Bitmap b=frames[index];float left=geometry[2],right=geometry[3],scale=CharacterViewport.scale(geometry[24],width,height),head=(width-(right-left)*scale)*.5f-left*scale,x=head-geometry[index*4]*scale,y=CharacterViewport.top(height*.985f-geometry[index*4+1]*scale,0,scale,height);dst.set(x,y,x+b.getWidth()*scale,y+b.getHeight()*scale);paint.setAlpha(alpha);c.drawBitmap(b,null,dst,paint);}
 boolean draw(Canvas c,int width,int height,long now,boolean quiet){if(quiet){cancel();return false;}if(!active(now)||frames==null||width<=0||height<=0)return false;int index=frame(now-started,reverse);single(c,width,height,index,255);paint.setAlpha(255);return true;}

 void release(){generation++;cancel();loading=false;if(frames!=null)for(Bitmap b:frames)b.recycle();frames=null;geometry=null;retryAfter=0;}
}
